import {POOL,clone,move,solved,createCertifiedPuzzle,symbolCount,budget,normalize} from './engine.js';
const $=id=>document.getElementById(id);let save;try{save=normalize(JSON.parse(localStorage.getItem('chemlab_v50')))}catch{save=normalize(null)}
const colors=['#cc8941','#49bdb5','#a777db','#dd6f7c','#599fcf','#b1b452','#dfbb56','#8fbce6','#b688d9','#97bf78','#cb9781','#7ba4d2','#e79d64','#72c8b0','#ca7fba','#88abca','#bbbe87','#b18ed4','#c5a457'];
const names=['Натрій','Хлор','Залізо','Кисень','Вуглець','Водень','Золото','Літій','Гелій','Берилій','Бор','Азот','Фтор','Неон','Магній','Алюміній','Кремній','Фосфор','Сірка'];
let puzzle,tubes,moves,history=[],selected=-1,assisted=false,reserve=false,locked=false,ended=false,seed=0,sound=true,ctx,storageWarn=false;
const persist=()=>{try{localStorage.setItem('chemlab_v50',JSON.stringify(save))}catch{storageWarn=true;}};
const say=s=>$('feedback').textContent=s;
function tone(f=500){if(!sound)return;try{ctx??=new (window.AudioContext||window.webkitAudioContext)();ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(f,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(f*.55,ctx.currentTime+.15);g.gain.setValueAtTime(.045,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.21)}catch{}}
function newSeed(){return crypto.getRandomValues(new Uint32Array(1))[0]}
function start(exact=false){if(locked)return;seed=exact?seed:newSeed();const count=symbolCount(save.level);while(save.discovered.length<count)save.discovered.push(POOL[save.discovered.length]);if(!exact||!puzzle||puzzle.level!==save.level)puzzle=createCertifiedPuzzle(save.discovered.slice(0,count),save.level,seed,exact?[]:save.recentPuzzles);tubes=clone(puzzle.tubes);moves=budget(puzzle,save.level);history=[];selected=-1;assisted=false;reserve=false;ended=false;save.recentPuzzles=[...save.recentPuzzles.filter(k=>k!==puzzle.key),puzzle.key].slice(-3);persist();$('modal').close();render();say(storageWarn?'Збереження недоступне у цьому браузері':'Торкнись колби, потім обери, куди перелити');}
function render(){const complete=tubes.filter(a=>a.length===4&&a.every(s=>s===a[0])).length;$('gold').textContent=save.gold;$('level').textContent=String(save.level).padStart(2,'0');$('moves').textContent=moves;$('completed').textContent=`${complete} / ${symbolCount(save.level)}`;$('mastery').textContent=save.nug;$('discovered').textContent=`${save.discovered.length} / 19`;$('chapter').textContent=save.level<4?'РОЗДІЛ I · ПЕРШЕ СВІТЛО':save.level<8?'РОЗДІЛ II · СПЕКТР':save.level<15?'РОЗДІЛ III · РЕЗОНАНС':'РОЗДІЛ IV · ВЕЛИКИЙ СИНТЕЗ';$('undo').disabled=!history.length||locked||ended;$('reserve').disabled=reserve||locked||ended;$('hint').disabled=locked||ended;$('restart').disabled=locked;$('board').innerHTML=tubes.map((t,i)=>{const done=t.length===4&&t.every(s=>s===t[0]);return `<button class="tube-wrap ${selected===i?'selected':''} ${done?'done':''}" data-tube="${i}" aria-label="Колба ${i+1}: ${t.length?t.join(', '):'порожня'}" aria-pressed="${selected===i}"><span class="rim"></span><span class="tube">${t.map(s=>`<span class="token" style="--c:${colors[POOL.indexOf(s)]}">${s}</span>`).join('')}</span><span class="tube-number">${done?'✓':String(i+1).padStart(2,'0')}</span></button>`}).join('');}
$('board').addEventListener('click',async e=>{const button=e.target.closest('[data-tube]');if(!button||locked||ended)return;const b=Number(button.dataset.tube);if(selected<0){if(tubes[b].length){selected=b;tone(420);render();say(`Колба ${b+1} обрана · обери колбу з ${tubes[b].at(-1)} або порожню`)}return}if(selected===b){selected=-1;render();return}const a=selected,next=move(tubes,a,b);if(!next){if(tubes[b].length)selected=b;render();say('Переливай на такий самий елемент або в порожню колбу');tone(160);return}locked=true;history.push({tubes:clone(tubes),moves});document.querySelector(`[data-tube="${a}"]`).classList.add('pouring');tone(640);navigator.vibrate?.(12);await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?0:320));tubes=next;moves--;selected=-1;locked=false;render();if(solved(tubes))win();else if(moves<=0)lose();else say('Добре! Продовжуй збирати однакові елементи');});
function modal(html){$('modalbody').innerHTML=html;$('modal').showModal();}
$('close').onclick=()=>$('modal').close();
function win(){if(ended)return;ended=true;const l=save.level,reward=50+l*5+Math.min(30,moves*2);save.gold+=reward;save.xp+=25+l*2;save.score+=100+l*10+moves*5;save.streak++;save.bestStreak=Math.max(save.streak,save.bestStreak);if(!assisted)save.nug++;save.level++;let discovered=null;const target=Math.min(19,3+Math.floor((save.level-1)/2));while(save.discovered.length<target){discovered=POOL[save.discovered.length];save.discovered.push(discovered)}persist();render();$('level').textContent=String(l).padStart(2,'0');tone(880);modal(`<div class="eyebrow">ЕКСПЕРИМЕНТ ${l} ЗАВЕРШЕНО</div><div class="reward">✦</div><h2>Чистий синтез!</h2><p>+${reward} монет · +${25+l*2} XP<br>${assisted?'Експеримент із підтримкою':'+1 кристал майстерності'} · Серія ${save.streak}</p>${discovered?`<p>Відкрито новий елемент: <b>${discovered}</b></p>`:''}<button class="primary" id="next">Експеримент ${save.level} →</button>`);$('next').onclick=()=>start();}
function lose(){ended=true;save.streak=0;persist();render();modal('<div class="reward">↻</div><h2>Спробуй інший шлях</h2><p>Ходи закінчилися. Цей експеримент має розв’язок. Почни ще раз або візьми нову комбінацію.</p><button class="primary" id="retry">Повторити цей рівень</button><button class="secondary" id="shuffle">Нова комбінація</button>');$('retry').onclick=()=>start(true);$('shuffle').onclick=()=>start();}
$('undo').onclick=()=>{if(locked||ended||!history.length)return;const h=history.pop();tubes=h.tubes;moves=h.moves;assisted=true;selected=-1;render();say('Хід скасовано · використано допомогу');};
$('hint').onclick=()=>{if(locked||ended)return;assisted=true;for(let a=0;a<tubes.length;a++)for(let b=0;b<tubes.length;b++)if(move(tubes,a,b)){selected=a;render();for(const i of [a,b])document.querySelector(`[data-tube="${i}"]`).classList.add('hinted');say(`Можливий хід: колба ${a+1} → колба ${b+1}`);return}say('Немає доступних ходів. Скасуй хід або додай колбу');};
$('reserve').onclick=()=>{if(reserve||locked||ended)return;reserve=true;assisted=true;tubes.push([]);selected=-1;render();say('Резервна колба готова · використано допомогу');};
$('restart').onclick=()=>{if(locked)return;modal('<h2>Почати заново?</h2><p>Поточні ходи буде скинуто. Монети та відкриття збережуться.</p><button class="primary" id="same">Та сама комбінація</button><button class="secondary" id="new">Нова комбінація</button>');$('same').onclick=()=>start(true);$('new').onclick=()=>start();};
function atlas(){modal(`<div class="eyebrow">КОЛЕКЦІЯ ДОСЛІДНИКА</div><h2>Твій атлас елементів</h2><p>${save.discovered.length} з 19 відкрито · ${save.xp} XP<br>Нові символи відкриваються під час проходження</p><div class="atlas">${POOL.map((s,i)=>`<div class="element ${save.discovered.includes(s)?'':'locked'}" style="color:${colors[i]}">${save.discovered.includes(s)?s:'?'}<small>${save.discovered.includes(s)?names[i]:'Закрито'}</small></div>`).join('')}</div><p>Символи у грі вигадані ігрові фішки. Це не інструкції для хімічних дослідів.</p>`)}$('atlas').onclick=atlas;$('collection').onclick=atlas;
$('settings').onclick=()=>{modal(`<h2>Лабораторія</h2><p>Збери по 4 однакові символи в кожній непорожній колбі. Переноситься верхня група однакових символів. Перемога без допомоги дає кристал майстерності.</p><button class="secondary" id="sound">Звук: ${sound?'увімкнено':'вимкнено'}</button><p>Оформлення колб · ${save.nug} кристалів</p><div class="skins">${[['default',0,'Класичне скло'],['neon',3,'Неонове скло'],['violet',6,'Фіолетове скло'],['gold',10,'Золоте скло']].map(([s,n,title])=>`<button data-skin="${s}" ${save.nug<n?'disabled':''}>${title} ${n?'· '+n+' ✦':''}</button>`).join('')}</div><p>Рекордна серія: ${save.bestStreak} · Рахунок: ${save.score}<br>Прогрес зберігається на цьому пристрої</p>`);$('sound').onclick=()=>{sound=!sound;$('sound').textContent=`Звук: ${sound?'увімкнено':'вимкнено'}`;try{localStorage.setItem('chemlab_sound',String(sound))}catch{}};document.querySelectorAll('[data-skin]').forEach(b=>{if(b.tagName==='BUTTON')b.onclick=()=>{const s=b.dataset.skin;$('game').dataset.skin=s;try{localStorage.setItem('chemlab_cosmetic',s)}catch{};b.textContent+=' ✓';}});};
try{sound=localStorage.getItem('chemlab_sound')!=='false';const s=localStorage.getItem('chemlab_cosmetic');const thresholds={default:0,neon:3,violet:6,gold:10};if(s in thresholds&&save.nug>=thresholds[s])$('game').dataset.skin=s}catch{}
start();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
